text:
.loca-listarea {display : block; }
.brd-listarea {display : none; }
.board-listarea {display : block; }
.nf-header {display : none; }
.header-pcarea {display : block; }
#korfooter {display : block; }
#privacy-modal{width:1024px;margin-top:0px !important}
#privacy-modal .pop-conts{height:420px}

@media(max-width:1023px){
    .loca-listarea {display : none; }
    .brd-listarea {display : block; }
    .board-listarea {display : none; }
    .nf-header {display : block; }
    .header-pcarea {display : none; }
    #korfooter {display : block; }
    .mobile-none{display:none;}
    .guide-categorylist li{width:12.5%}
    .guide-categorylist li img {width:100px}
    .guide-categorylist li .gimg-area {width: 90%;}
}
@media(max-width:780px){.guide-categorylist li{width:16.6%}}
@media(max-width:640px){.guide-categorylist li{width:20%}}
@media(max-width:480px){.guide-categorylist li{width:25%}}
@media(max-width:415px){.guide-categorylist li{width:33%}}

select:focus{
    outline : 2px solid red;}
    .ctimpop ul li{padding:0px}
